// Equipment cost catalogue wrapper (DESIGN §4.6): types, lookup, provenance. The coefficients live in equipment.gen.ts
// (generated by scripts/port-costs.py from docs/research/costs_turton.py and costs.md); nothing here retypes a number.
import type { Conf } from '../sim/types';
import { CEPCI_CONF_GEN, CEPCI_GEN, EQUIPMENT_GEN } from './equipment.gen';

export type Material = 'CS' | 'SS' | 'Ni';
export type CostForm = 'fbm' | 'bm' | 'fbm_fp' | 'bm_vessel' | 'towler';

/** A cost row (plain JSON). `K` is absent for the Towler rows (C = a + b S^n). */
export interface EquipmentRec {
  key: string;
  label: string;
  /** Size variable unit: kW, m2, m3, L/s, kg/h. */
  unit: string;
  K: readonly [number, number, number] | null;
  Amin: number;
  Amax: number;
  form: CostForm;
  factors: {
    fbm?: Readonly<Partial<Record<Material, number>>>;
    B?: readonly [number, number];
    FM?: Readonly<Partial<Record<Material, number>>>;
    a?: number; b?: number; n?: number;
  } | null;
  fp: { C?: readonly [number, number, number]; Pmin?: number; Pmax?: number; vessel?: { S: number; tmin: number } } | null;
  /** CEPCI year the correlation's dollars are in (2001 Turton, 2010 Towler and Sinnott). */
  basis: number;
  confK: Conf;
  confF: Conf;
  /** Worst of confK and confF. */
  conf: Conf;
  src: string;
}

export const EQUIPMENT: readonly EquipmentRec[] = EQUIPMENT_GEN as unknown as readonly EquipmentRec[];
export const EQUIPMENT_KEYS: readonly string[] = EQUIPMENT.map((e) => e.key);
export const CEPCI: Readonly<Record<string, number>> = CEPCI_GEN;
export const CEPCI_CONF: Readonly<Record<string, Conf>> = CEPCI_CONF_GEN as Record<string, Conf>;
/** Dollar year of every game price (DESIGN §4.6 decision). */
export const GAME_YEAR = 2023;

const BY_KEY: Record<string, EquipmentRec> = {};
for (const e of EQUIPMENT) BY_KEY[e.key] = e;

export function findEquipment(key: string): EquipmentRec | undefined { return Object.prototype.hasOwnProperty.call(BY_KEY, key) ? BY_KEY[key] : undefined; }

/**
 * Game equipment names that map onto a cost row (the flowsheet unit types of DESIGN §8.1 call these).
 * `via` is the catalogue row; the sizing rule for each lives in sim/econ/capex.ts.
 */
export const EQUIPMENT_ALIASES: Readonly<Record<string, string>> = {
  flash_drum: 'vessel_vertical', converter: 'vessel_vertical', packed_bed_converter: 'vessel_vertical', absorber: 'vessel_vertical',
  furnace: 'fired_heater', cooler: 'air_cooler', whb: 'steam_boiler', boiler: 'steam_boiler', hx: 'hx_floating_head', reactor: 'vessel_vertical',
};

/** The cost types M2 must have (DESIGN §4.6 / brief): each resolves to a catalogue row directly or by alias. */
export const MUST_SHIP_TYPES: readonly string[] = [
  'compressor', 'hx_floating_head', 'fired_heater', 'vessel_vertical', 'converter', 'packed_bed_converter', 'flash_drum', 'air_cooler', 'steam_boiler', 'absorber', 'pump',
];
